function estateAccountSave(PDO $pdo,int $admin,int $id,array $in):void {if(!in_array($id,[1,2],true))throw new InvalidArgumentException('Genau zwei Immobilienkonten vorhanden.');$data=['alias'=>opsText($in,'alias',190,true),'reference'=>opsText($in,'reference',190)];estateTx($pdo,$admin,function()use($pdo,$admin,$id,$in,$data){$old=estateLock($pdo,'estate_bank_accounts',$id,opsVersion($in));$pdo->prepare('UPDATE estate_bank_accounts SET alias=?,reference=?,row_version=row_version+1 WHERE id=?')->execute([...array_values($data),$id]);estateEvent($pdo,$admin,'account',$id,'account_updated',$old,$data);});}
function estateExistingBankRows(PDO $pdo,int $account,array $rows):array {$keys=array_column($rows,'source_key');if(!$keys)return [];$q=$pdo->prepare('SELECT source_key,record_hash FROM estate_bank_transactions WHERE account_id=? AND source_key IN('.implode(',',array_fill(0,count($keys),'?')).')');$q->execute([$account,...$keys]);return array_column($q->fetchAll(),'record_hash','source_key');}
function estateBankPreview(PDO $pdo,int $admin,int $account,string $raw,array $map,string $locale='de',string $separator=';',string $format='csv'):string {
 if(!in_array($account,[1,2],true))throw new InvalidArgumentException('Volksbank-Kontozuordnung1 oder2 erforderlich.');$rows=bankParseStatement($raw,$map,$locale,$separator,1000,$format);$ibanHash=$format==='camt'?hash('sha256',bankIban((string)($map['expected_iban']??''))):null;return estateTx($pdo,$admin,function()use($pdo,$admin,$account,$rows,$raw,$ibanHash){if($ibanHash)bankAssertIbanBinding($pdo,'estate_bank_accounts',$account,$ibanHash);$a=estateLock($pdo,'estate_bank_accounts',$account);if($ibanHash&&!empty($a['import_iban_hash'])&&!hash_equals($a['import_iban_hash'],$ibanHash))throw new RuntimeException('CAMT-Kontoidentität passt nicht zum gewählten Volksbank-Konto.');$checkPossible=$ibanHash!==null||!empty($a['import_iban_hash']);$possible=bankPossibleDuplicates($pdo,'estate_bank_transactions',$account,$rows,$checkPossible);$old=estateExistingBankRows($pdo,$account,$rows);$conflicts=[];$duplicates=0;foreach($rows as $row)if(isset($old[$row['source_key']])){if(!hash_equals($old[$row['source_key']],$row['record_hash']))$conflicts[]=$row['external_id'];else $duplicates++;}$token=bin2hex(random_bytes(32));$payload=['account_id'=>$account,'iban_hash'=>$ibanHash,'check_possible'=>$checkPossible,'possible_duplicates'=>$possible,'file_hash'=>hash('sha256',$raw),'rows'=>$rows,'conflicts'=>$conflicts,'duplicates'=>$duplicates];$pdo->prepare("INSERT INTO estate_proposals(token,kind,admin_id,fingerprint,payload) VALUES(?,'bank',?,?,?)")->execute([$token,$admin,hash('sha256',json_encode($a,JSON_THROW_ON_ERROR)),json_encode($payload,JSON_THROW_ON_ERROR)]);return $token;});
}
function estateBankApply(PDO $pdo,int $admin,string $token,bool $possibleReviewed=false):int {
 return estateTx($pdo,$admin,function()use($pdo,$admin,$token,$possibleReviewed){$p=estateGetProposal($pdo,$admin,$token,'bank');if($p['applied_at'])return 0;$payload=json_decode($p['payload'],true,64,JSON_THROW_ON_ERROR);$account=(int)$payload['account_id'];if(!empty($payload['iban_hash']))bankAssertIbanBinding($pdo,'estate_bank_accounts',$account,$payload['iban_hash'],true);$a=estateLock($pdo,'estate_bank_accounts',$account);if(!hash_equals($p['fingerprint'],hash('sha256',json_encode($a,JSON_THROW_ON_ERROR))))throw new RuntimeException('Kontobezeichnung seit Vorschau geändert. Import neu prüfen.');if($payload['conflicts'])throw new RuntimeException('Quellen-ID-Konflikte: keine stillen Umsatzänderungen.');bankReviewPossible($payload['possible_duplicates']??[],bankPossibleDuplicates($pdo,'estate_bank_transactions',$account,$payload['rows'],!empty($payload['check_possible'])),$possibleReviewed);$old=estateExistingBankRows($pdo,$account,$payload['rows']);if(!empty($payload['iban_hash'])){if(!empty($a['import_iban_hash'])&&!hash_equals($a['import_iban_hash'],$payload['iban_hash']))throw new RuntimeException('CAMT-Kontoidentität inzwischen geändert.');$pdo->prepare('UPDATE estate_bank_accounts SET import_iban_hash=? WHERE id=?')->execute([$payload['iban_hash'],$account]);}$count=0;foreach($payload['rows'] as $row){if(isset($old[$row['source_key']])){if(!hash_equals($old[$row['source_key']],$row['record_hash']))throw new RuntimeException('Importbestand geändert; Konflikt prüfen.');continue;}$pdo->prepare('INSERT INTO estate_bank_transactions(account_id,source_key,record_hash,external_id,booked_on,value_on,amount_cents,currency,purpose,counterparty) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$account,$row['source_key'],$row['record_hash'],$row['external_id'],$row['booked_on'],$row['value_on'],$row['amount_cents'],$row['currency'],$row['purpose'],$row['counterparty']]);$count++;}$pdo->prepare('UPDATE estate_proposals SET applied_at=UTC_TIMESTAMP() WHERE token=?')->execute([$token]);estateEvent($pdo,$admin,'bank_import',0,'bank_imported',[],['account_id'=>$account,'count'=>$count,'file_hash'=>$payload['file_hash'],'similarity_reviewed'=>$possibleReviewed]);return $count;});
}
function estatePayment(PDO $pdo,int $admin,int $bank,string $date,int $amount,string $description,string $request):int {
 if(!preg_match('/^[a-f0-9]{64}$/D',$request)||$bank<0||(!$bank&&(!$amount||abs($amount)>99999999999)))throw new InvalidArgumentException('Zahlung/Anfrage ungültig.');$description=opsText(['description'=>$description],'description',1000,true);if(!$bank)estateDate($date);
 return estateTx($pdo,$admin,function()use($pdo,$admin,$bank,$date,$amount,$description,$request){if($bank){$t=estateLock($pdo,'estate_bank_transactions',$bank);$date=$t['booked_on'];$amount=(int)$t['amount_cents'];if(!$amount)throw new RuntimeException('Nullumsatz ist keine Mietzahlung.');$q=$pdo->prepare('SELECT id FROM estate_expenses WHERE transaction_id=? UNION ALL SELECT id FROM estate_transfers WHERE outgoing_id=? OR incoming_id=?');$q->execute([$bank,$bank,$bank]);if($q->fetch())throw new RuntimeException('Umsatz bereits als Ausgabe/Umbuchung zugeordnet.');$q=$pdo->prepare('SELECT * FROM estate_payments WHERE bank_transaction_id=?');$q->execute([$bank]);if($old=$q->fetch())return (int)$old['id'];}
 $q=$pdo->prepare('SELECT * FROM estate_payments WHERE request_key=?');$q->execute([$request]);if($old=$q->fetch()){if((int)$old['bank_transaction_id']!==$bank||$old['paid_on']!==$date||(int)$old['amount_cents']!==$amount||$old['description']!==$description)throw new RuntimeException('Anfrageidentität mit abweichenden Zahlungsdaten.');return (int)$old['id'];}$pdo->prepare('INSERT INTO estate_payments(bank_transaction_id,paid_on,amount_cents,description,request_key,created_by) VALUES(?,?,?,?,?,?)')->execute([$bank?:null,$date,$amount,$description,$request,$admin]);$id=(int)$pdo->lastInsertId();estateEvent($pdo,$admin,'payment',$id,'payment_recorded',[],['bank_transaction_id'=>$bank?:null,'date'=>$date,'amount_cents'=>$amount]);return $id;});
}
function estateAllocate(PDO $pdo,int $admin,int $payment,int $lease,?int $charge,string $component,int $amount,string $request,?string $from=null,?string $to=null):int {
 estateComponent($component);if(!$amount||abs($amount)>99999999999||!preg_match('/^[a-f0-9]{64}$/D',$request)||($component==='deposit')!==($charge===null))throw new InvalidArgumentException('Zahlungszuordnung ungültig.');
 return estateTx($pdo,$admin,function()use($pdo,$admin,$payment,$lease,$charge,$component,$amount,$request,$from,$to){$p=estateLock($pdo,'estate_payments',$payment);$l=estateLock($pdo,'estate_leases',$lease);if($l['occupancy_kind']!=='tenant')throw new RuntimeException('Keine Mietzahlung für Eigennutzung.');$q=$pdo->prepare('SELECT * FROM estate_allocations WHERE request_key=?');$q->execute([$request]);if($old=$q->fetch()){if((int)$old['payment_id']!==$payment||(int)$old['lease_id']!==$lease||(int)$old['charge_id']!==($charge??0)||$old['component']!==$component||(int)$old['amount_cents']!==$amount||($from!==null&&$old['allocation_from']!==$from)||($to!==null&&$old['allocation_to']!==$to))throw new RuntimeException('Anfrageidentität abweichend.');return (int)$old['id'];}$q=$pdo->prepare('SELECT COALESCE(SUM(amount_cents),0) FROM estate_allocations WHERE payment_id=?');$q->execute([$payment]);$used=(int)$q->fetchColumn();$total=(int)$p['amount_cents'];if(($amount>0)!==($total>0)||($total>0&&($used+$amount>$total||$used+$amount<0))||($total<0&&($used+$amount<$total||$used+$amount>0)))throw new RuntimeException('Zuordnung überschreitet den verfügbaren Zahlungsbetrag/Vorzeichen.');
 if($charge){$c=estateChargeBalance($pdo,$charge);if((int)$c['lease_id']!==$lease)throw new RuntimeException('Forderung gehört zu anderem Vertrag.');$paid=$c['paid'][$component];$due=$c[$component.'_cents'];}
 else{$q=$pdo->prepare("SELECT COALESCE(SUM(amount_cents),0) FROM estate_allocations WHERE lease_id=? AND component='deposit'");$q->execute([$lease]);$paid=(int)$q->fetchColumn();$due=(int)$l['deposit_cents'];}
 $atFrom=null;$atTo=null;if(in_array($component,['operating','heating'],true)){
 $min=max($c['month'],$l['starts_on']);$max=min((new DateTimeImmutable($c['month']))->format('Y-m-t'),$l['ends_on']?:'9999-12-31');
 if(($from===null)!==($to===null))throw new RuntimeException('Zuordnungszeitraum vollständig angeben.');$atFrom=$from===null?$min:estateDate($from);$atTo=$to===null?$max:estateDate($to);if($atFrom<$min||$atTo>$max||$atFrom>$atTo)throw new RuntimeException('Vorauszahlungszuordnung außerhalb des Forderungs-/Mietzeitraums.');
