}
function estateReverseAllocation(PDO $pdo,int $admin,int $allocation,string $reason,string $request):int {
 $reason=opsText(['reason'=>$reason],'reason',1000,true);if(!preg_match('/^[a-f0-9]{64}$/D',$request))throw new InvalidArgumentException('Anfrage ungültig.');return estateTx($pdo,$admin,function()use($pdo,$admin,$allocation,$reason,$request){$old=estateLock($pdo,'estate_allocations',$allocation);if($old['reversal_of'])throw new RuntimeException('Gegenzeile nicht erneut rückgängig machen. Zuordnung neu bestätigen.');$q=$pdo->prepare('SELECT id FROM estate_allocations WHERE reversal_of=?');$q->execute([$allocation]);if($id=$q->fetchColumn())return (int)$id;
 if($old['charge_id']){$balance=estateChargeBalance($pdo,(int)$old['charge_id']);$paid=$balance['paid'][$old['component']];}
 else{$sum=$pdo->prepare("SELECT COALESCE(SUM(amount_cents),0) FROM estate_allocations WHERE lease_id=? AND component='deposit'");$sum->execute([$old['lease_id']]);$paid=(int)$sum->fetchColumn();}
 if($paid-(int)$old['amount_cents']<0)throw new RuntimeException('Spätere Rückzahlung/Zuordnung zuerst korrigieren; kein negativer Komponentenstand.');
 $pdo->prepare('INSERT INTO estate_allocations(payment_id,lease_id,charge_id,component,amount_cents,allocation_from,allocation_to,reversal_of,reason,request_key,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$old['payment_id'],$old['lease_id'],$old['charge_id'],$old['component'],-(int)$old['amount_cents'],$old['allocation_from']??null,$old['allocation_to']??null,$allocation,$reason,$request,$admin]);$id=(int)$pdo->lastInsertId();estateEvent($pdo,$admin,'allocation',$id,'allocation_reversed',[],['original'=>$allocation,'reason'=>$reason]);return $id;});
}
function estatePairTransfer(PDO $pdo,int $admin,int $out,int $in,string $reason):int {
 $reason=opsText(['reason'=>$reason],'reason',1000,true);return estateTx($pdo,$admin,function()use($pdo,$admin,$out,$in,$reason){$a=estateLock($pdo,'estate_bank_transactions',$out);$b=estateLock($pdo,'estate_bank_transactions',$in);if((int)$a['amount_cents']>=0||(int)$b['amount_cents']<=0||(int)$a['amount_cents']!==-(int)$b['amount_cents']||$a['account_id']===$b['account_id']||$a['currency']!==$b['currency'])throw new RuntimeException('Umbuchung benötigt entgegengesetzte gleiche Beträge auf den zwei verschiedenen Konten.');$q=$pdo->prepare('SELECT * FROM estate_transfers WHERE outgoing_id IN (?,?) OR incoming_id IN (?,?)');$q->execute([$out,$in,$out,$in]);if($old=$q->fetch()){if((int)$old['outgoing_id']===$out&&(int)$old['incoming_id']===$in)return (int)$old['id'];throw new RuntimeException('Umsatz gehört bereits zu anderer Umbuchung.');}$q=$pdo->prepare('SELECT id FROM estate_payments WHERE bank_transaction_id IN (?,?) UNION ALL SELECT id FROM estate_expenses WHERE transaction_id IN (?,?)');$q->execute([$out,$in,$out,$in]);if($q->fetch())throw new RuntimeException('Bereits als Zahlung/Ausgabe zugeordnet.');$pdo->prepare('INSERT INTO estate_transfers(outgoing_id,incoming_id,reason,created_by) VALUES(?,?,?,?)')->execute([$out,$in,$reason,$admin]);$id=(int)$pdo->lastInsertId();estateEvent($pdo,$admin,'transfer',$id,'transfer_confirmed',[],['outgoing'=>$out,'incoming'=>$in]);return $id;});
}
function estateRentLedger(PDO $pdo,string $month,int $building=0):array {
 $month=estateMonth($month);$hasSettlement=(int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='320_estate_settlements'")->fetchColumn();$settledSql=$hasSettlement?"EXISTS(SELECT 1 FROM estate_settlements s WHERE s.building_id=u.building_id AND s.period_from<=GREATEST(c.month,l.starts_on) AND s.period_to>=LEAST(LAST_DAY(c.month),COALESCE(l.ends_on,LAST_DAY(c.month))))":'0';$q=$pdo->prepare("SELECT ".$settledSql." settled_period,c.*,u.label,u.building_id,b.name building_name,t.name tenant_name,COALESCE(a.rent,0) adjust_rent,COALESCE(a.operating,0) adjust_operating,COALESCE(a.heating,0) adjust_heating,COALESCE(p.rent,0) paid_rent,COALESCE(p.operating,0) paid_operating,COALESCE(p.heating,0) paid_heating FROM estate_rent_charges c JOIN estate_leases l ON l.id=c.lease_id JOIN estate_units u ON u.id=l.unit_id JOIN estate_buildings b ON b.id=u.building_id JOIN estate_tenants t ON t.id=l.tenant_id LEFT JOIN(SELECT charge_id,SUM(IF(component='rent',amount_cents,0)) rent,SUM(IF(component='operating',amount_cents,0)) operating,SUM(IF(component='heating',amount_cents,0)) heating FROM estate_charge_adjustments GROUP BY charge_id)a ON a.charge_id=c.id LEFT JOIN(SELECT charge_id,SUM(IF(component='rent',amount_cents,0)) rent,SUM(IF(component='operating',amount_cents,0)) operating,SUM(IF(component='heating',amount_cents,0)) heating FROM estate_allocations GROUP BY charge_id)p ON p.charge_id=c.id WHERE c.month=?".($building?' AND u.building_id=?':'').' ORDER BY b.name,u.label,c.id LIMIT 501');$q->execute([$month,...($building?[$building]:[])]);$rows=$q->fetchAll();if(count($rows)>500)throw new RuntimeException('Mietkonto auf Gebäude eingrenzen.');foreach($rows as &$row){$row['due_cents']=0;$row['paid_cents']=0;foreach(['rent','operating','heating'] as $k){$row[$k.'_cents']=(int)$row[$k.'_cents']+(int)$row['adjust_'.$k];$row['due_cents']+=$row[$k.'_cents'];$row['paid_cents']+=(int)$row['paid_'.$k];}$row['open_cents']=$row['due_cents']-$row['paid_cents'];}unset($row);return $rows;
}
function estateTransferSuggestions(PDO $pdo):array {return $pdo->query("SELECT a.id outgoing_id,b.id incoming_id,a.amount_cents,a.booked_on out_date,b.booked_on in_date FROM estate_bank_transactions a JOIN estate_bank_transactions b ON a.account_id<>b.account_id AND a.amount_cents=-b.amount_cents AND a.amount_cents<0 AND b.booked_on BETWEEN DATE_SUB(a.booked_on,INTERVAL 3 DAY) AND DATE_ADD(a.booked_on,INTERVAL 3 DAY) WHERE NOT EXISTS(SELECT 1 FROM estate_transfers t WHERE t.outgoing_id=a.id OR t.incoming_id=b.id) AND NOT EXISTS(SELECT 1 FROM estate_payments p WHERE p.bank_transaction_id IN(a.id,b.id)) AND NOT EXISTS(SELECT 1 FROM estate_expenses e WHERE e.transaction_id IN(a.id,b.id)) ORDER BY a.id DESC,b.id DESC LIMIT 30")->fetchAll();}
/** Pure local proposals only. Score is a heuristic, never statistical confidence. */
function estateRentSuggestions(array $transactions,array $ledger):array {
 $candidates=[];foreach($ledger as $c)if((int)$c['open_cents']>0&&empty($c['settled_period']))$candidates[]=['kind'=>'estate_rent','id'=>(int)$c['id'],'lease_id'=>(int)$c['lease_id'],'name'=>$c['tenant_name'],'date'=>$c['due_on'],'remaining_cents'=>(int)$c['open_cents'],'month'=>$c['month']];$out=[];
 foreach(array_slice($transactions,0,200) as $t){if((int)$t['amount_cents']<=0||!empty($t['payment_id'])||!empty($t['expense_id'])||!empty($t['transfer_id']))continue;foreach(array_slice(financeMatch($t,$candidates),0,3) as $m)if($m['score']>=60)$out[]=['transaction_id'=>(int)$t['id'],'account_id'=>(int)$t['account_id'],'match'=>$m];if(count($out)>=30)break;}return array_slice($out,0,30);
}
function estateFinancialOverview(PDO $pdo,string $from,string $to):array {
 estateDate($from);estateDate($to);if($from>$to)throw new RuntimeException('Finanzzeitraum ungültig.');$buildings=$pdo->query('SELECT id,name FROM estate_buildings ORDER BY id LIMIT 501')->fetchAll();if(count($buildings)>500)throw new RuntimeException('Finanzübersicht auf Gebäude eingrenzen.');$q=$pdo->prepare("SELECT u.building_id,SUM(a.amount_cents) amount FROM estate_allocations a JOIN estate_payments p ON p.id=a.payment_id JOIN estate_leases l ON l.id=a.lease_id JOIN estate_units u ON u.id=l.unit_id WHERE a.component<>'deposit' AND p.paid_on BETWEEN ? AND ? GROUP BY u.building_id");$q->execute([$from,$to]);$income=array_column($q->fetchAll(),'amount','building_id');$q=$pdo->prepare('SELECT e.building_id,SUM(-t.amount_cents) amount FROM estate_expenses e JOIN estate_bank_transactions t ON t.id=e.transaction_id WHERE t.booked_on BETWEEN ? AND ? GROUP BY e.building_id');$q->execute([$from,$to]);$expense=array_column($q->fetchAll(),'amount','building_id');$rows=[];foreach($buildings as $b){$in=(int)($income[$b['id']]??0);$out=(int)($expense[$b['id']]??0);$rows[]=['building_id'=>(int)$b['id'],'name'=>$b['name'],'income_cents'=>$in,'expense_cents'=>$out,'cash_surplus_cents'=>$in-$out];}return $rows;
}
